    private static function reduceSelectCore(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $distinct = false;
            $columns  = [];
            $from     = null;
            $joins    = [];
            $groupBy  = null;
            $where    = null;
            $having   = null;

            foreach ($children as $child) {
                if (\is_string($child)) {
                    if (\strtoupper($child) === 'DISTINCT') {
                        $distinct = true;
                    }
                } elseif ($child instanceof \Inilim\SqliteParser\Ast\Statement\ResultColumnList) {
                    $columns = $child->items;
                } elseif ($child instanceof \Inilim\SqliteParser\Ast\Statement\FromClause) {
                    $from  = $child->base;
                    $joins = $child->joins;
                } elseif ($child instanceof \Inilim\SqliteParser\Ast\Statement\GroupByClause) {
                    $groupBy = $child;
                } elseif ($child instanceof \Inilim\SqliteParser\Ast\Statement\WhereClause) {
                    $where = $child->expression;
                } elseif ($child instanceof \Inilim\SqliteParser\Ast\Statement\HavingClause) {
                    $having = $child->expression;
                }
            }

            return new \Inilim\SqliteParser\Ast\Statement\SelectStatement(
                columns: $columns,
                distinct: $distinct,
                from: $from,
                joins: $joins,
                where: $where,
                groupBy: $groupBy,
                having: $having,
            );
    }

