    private static function reduceFromClause(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $base  = null;
            $joins = [];

            foreach ($children as $child) {
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\TableReference && $base === null) {
                    $base = $child;
                } elseif ($child instanceof \Inilim\SqliteParser\Ast\Statement\JoinClause) {
                    $joins[] = $child;
                }
            }

            return new \Inilim\SqliteParser\Ast\Statement\FromClause($base, $joins);
    }

    private static function reduceTableReference(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $name          = null;
            $alias         = null;
            $subquery      = null;
            $columnAliases = [];

            $first = $children[0] ?? null;
            if (\is_string($first)) {
                $name = $first;
            } elseif ($first instanceof \Inilim\SqliteParser\Ast\Statement) {
                $subquery = $first;
            }

            $collectAliases = static function ($items) use (&$collectAliases, &$columnAliases, &$alias): void {
                foreach ($items as $item) {
                    if ($item instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                        if ($alias === null) {
                            $alias = $item->value;
                        }
                    } elseif (\is_string($item)) {
                        $columnAliases[] = $item;
                    } elseif (\is_array($item)) {
                        $collectAliases($item);
                    }
                }
            };

            foreach (\array_slice($children, 1) as $child) {
                if ($child instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                    $alias = $child->value;
                } elseif ($child instanceof \Inilim\SqliteParser\Ast\Statement\IdentListWrapper) {
                    $columnAliases = $child->items;
                } elseif (\is_string($child)) {
                    $columnAliases[] = $child;
                } elseif (\is_array($child)) {
                    $collectAliases($child);
                }
            }

            return new \Inilim\SqliteParser\Ast\Statement\TableReference(
                name: $name,
                alias: $alias,
                subquery: $subquery,
                columnAliases: $columnAliases === [] ? null : $columnAliases,
            );
    }

    private static function reduceJoinClause(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $natural = false;
            $type    = '';
            $table   = null;
            $on      = null;
            $using   = null;

            foreach ($children as $child) {
                if ($child instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                    $u = \strtoupper($child->value);
                    if ($u === 'NATURAL') {
                        $natural = true;
                    }
                    continue;
                }
                if (\is_string($child) && \in_array($child, ['INNER', 'LEFT', 'RIGHT', 'FULL', 'CROSS'], true)) {
                    $type = $child;
                    continue;
                }
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\TableReference) {
                    $table = $child;
                    continue;
                }
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\JoinConstraint) {
                    $on    = $child->on;
                    $using = $child->using;
                    continue;
                }
            }

            return new \Inilim\SqliteParser\Ast\Statement\JoinClause(
                type: $type,
                table: $table,
                on: $on,
                using: $using,
                natural: $natural,
            );
    }

    private static function reduceJoinType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        return $children instanceof \Phplrt\Contracts\Lexer\TokenInterface
                ? \strtoupper($children->value)
                : '';
    }

    private static function reduceJoinConstraint(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            foreach ($children as $child) {
                if ($child instanceof \Inilim\SqliteParser\Ast\Expression) {
                    return new \Inilim\SqliteParser\Ast\Statement\JoinConstraint(on: $child);
                }
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\IdentListWrapper) {
                    return new \Inilim\SqliteParser\Ast\Statement\JoinConstraint(using: $child->items);
                }
            }

            return null;
    }

    private static function reduceWhereClause(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $expression = null;
            foreach ($children as $child) {
                if ($child instanceof \Inilim\SqliteParser\Ast\Expression) {
                    $expression = $child;
                    break;
                }
            }

            if (!$expression instanceof \Inilim\SqliteParser\Ast\Expression) {
                throw new \LogicException('WHERE clause without expression');
            }

            return new \Inilim\SqliteParser\Ast\Statement\WhereClause($expression);
    }

    private static function reduceGroupByClause(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $expressions = [];
            foreach ($children as $child) {
                if ($child instanceof \Inilim\SqliteParser\Ast\Expression\ExpressionList) {
                    $expressions = $child->items;
                }
            }

            return new \Inilim\SqliteParser\Ast\Statement\GroupByClause($expressions);
    }

    private static function reduceHavingClause(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $expression = null;
            foreach ($children as $child) {
                if ($child instanceof \Inilim\SqliteParser\Ast\Expression) {
                    $expression = $child;
                    break;
                }
            }

            if (!$expression instanceof \Inilim\SqliteParser\Ast\Expression) {
                throw new \LogicException('HAVING clause without expression');
            }

            return new \Inilim\SqliteParser\Ast\Statement\HavingClause($expression);
    }

    private static function reduceCompoundOp(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
            $v = '';
            foreach ($children as $child) {
                if ($child instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                    $u = \strtoupper($child->value);
                    if ($u === 'ALL') {
                        $v .= ' ALL';
                    } else {
                        $v = $u;
                    }
                }
            }
            return \trim($v);
    }

    private static function reduceLimitClause(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        $children = \is_array($children) ? $children : [$children];
            $limit = (int) $children[0]->value;
            $offset = null;
            if (isset($children[1]) && $children[1] instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                $offset = (int) $children[1]->value;
            }

            return ['limit' => $limit, 'offset' => $offset];
    }

    private static function reduceInsertStatement(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
        
            $table          = null;
            $orAction       = null;
            $columns        = null;
            $valuesBody     = null;
            $selectBody     = null;
            $defaultValues  = false;
            $upsert         = null;
            $returning      = null;
        
            foreach ($children as $child) {
                if (\is_string($child)) {
                    $upper = \strtoupper($child);
                    if ($orAction === null
                        && \in_array($upper, ['REPLACE', 'IGNORE', 'ABORT', 'FAIL', 'ROLLBACK'], true)
                    ) {
                        $orAction = $upper;
                        continue;
                    }
                    if ($table === null) {
                        $table = $child;
                    }
                    continue;
                }
        
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\IdentListWrapper) {
                    $columns = $child->items;
                    continue;
                }
        
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\InsertValuesBody) {
                    $valuesBody = $child;
                    continue;
                }
        
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\InsertDefaultBody) {
                    $defaultValues = true;
                    continue;
                }
        
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement) {
                    $selectBody = $child;
                    continue;
                }
        
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\UpsertClause) {
                    $upsert = $child;
                    continue;
                }
        
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\ReturningClause) {
                    $returning = $child;
                    continue;
                }
            }
        
            return new \Inilim\SqliteParser\Ast\Statement\InsertStatement(
                table: $table ?? '',
                columns: $columns,
                rows: $valuesBody?->rows,
                select: $selectBody,
                defaultValues: $defaultValues,
                orAction: $orAction,
                upsert: $upsert,
                returning: $returning,
            );
    }

    private static function reduceOrAction(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
        
            foreach ($children as $child) {
                if ($child instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                    $v = \strtoupper($child->value);
                    if (\in_array($v, ['REPLACE', 'IGNORE', 'ABORT', 'FAIL', 'ROLLBACK'], true)) {
                        return $v;
                    }
                }
            }
        
            return '';
    }

    private static function reduceInsertValuesBody(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
        
            $rows = [];
            $collect = static function ($items) use (&$collect, &$rows): void {
                foreach ($items as $item) {
                    if ($item instanceof \Inilim\SqliteParser\Ast\Expression\ExpressionList) {
                        $rows[] = $item->items;
                    } elseif (\is_array($item)) {
                        $collect($item);
                    }
                }
            };
            $collect($children);
        
            return new \Inilim\SqliteParser\Ast\Statement\InsertValuesBody($rows);
    }

    private static function reduceInsertDefaultBody(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        return new \Inilim\SqliteParser\Ast\Statement\InsertDefaultBody();
    }

    private static function reduceUpsertClause(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
        
            $conflictTarget = null;
            $assignments    = null;
            $where          = null;
            $doNothing      = false;
        
            foreach ($children as $child) {
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\IdentListWrapper) {
                    $conflictTarget = $child->items;
                    continue;
                }
        
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\AssignmentList) {
                    $assignments = $child->items;
                    continue;
                }
        
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\WhereClause) {
                    $where = $child->expression;
                    continue;
                }
        
                if ($child instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                    if (\strtoupper($child->value) === 'NOTHING') {
                        $doNothing = true;
                    }
                    continue;
                }
            }
        
            return new \Inilim\SqliteParser\Ast\Statement\UpsertClause(
                conflictTarget: $conflictTarget,
                assignments: $doNothing ? null : $assignments,
                where: $where,
            );
    }

    private static function reduceAssignmentList(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
        
            $flat = [];
            \array_walk_recursive($children, static function ($item) use (&$flat): void {
                if ($item instanceof \Inilim\SqliteParser\Ast\Statement\Assignment) {
                    $flat[] = $item;
                }
            });
        
            return new \Inilim\SqliteParser\Ast\Statement\AssignmentList($flat);
    }

    private static function reduceAssignment(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
        
            $column = '';
            $value  = null;
        
            foreach ($children as $child) {
                if ($child instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                    $v   = $child->value;
                    $len = \strlen($v);
                    if ($len >= 2) {
                        $first = $v[0];
                        $last  = $v[$len - 1];
                        if (($first === '"' && $last === '"') || ($first === '`' && $last === '`')) {
                            $v = \substr($v, 1, -1);
                            $v = \str_replace($first . $first, $first, $v);
                        } elseif ($first === '[' && $last === ']') {
                            $v = \substr($v, 1, -1);
                        }
                    }
                    $column = $v;
                    continue;
                }
        
                if ($child instanceof \Inilim\SqliteParser\Ast\Expression) {
                    $value = $child;
                    continue;
                }
            }
        
            return new \Inilim\SqliteParser\Ast\Statement\Assignment($column, $value);
    }

    private static function reduceReturningClause(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
        
            $columns = [];
            foreach ($children as $child) {
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\ResultColumnList) {
                    $columns = $child->items;
                    break;
                }
            }
        
            return new \Inilim\SqliteParser\Ast\Statement\ReturningClause($columns);
    }

    private static function reduceUpdateStatement(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
        
            $table       = null;
            $orAction    = null;
            $assignments = [];
            $where       = null;
            $returning   = null;
        
            foreach ($children as $child) {
                if (\is_string($child)) {
                    $upper = \strtoupper($child);
                    if ($orAction === null
                        && \in_array($upper, ['REPLACE', 'IGNORE', 'ABORT', 'FAIL', 'ROLLBACK'], true)
                    ) {
                        $orAction = $upper;
                        continue;
                    }
                    if ($table === null) {
                        $table = $child;
                    }
                    continue;
                }
        
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\AssignmentList) {
                    $assignments = $child->items;
                    continue;
                }
        
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\WhereClause) {
                    $where = $child->expression;
                    continue;
                }
        
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\ReturningClause) {
                    $returning = $child;
                    continue;
                }
            }
        
            return new \Inilim\SqliteParser\Ast\Statement\UpdateStatement(
                table: $table ?? '',
                assignments: $assignments,
                where: $where,
                orAction: $orAction,
                returning: $returning,
            );
    }

    private static function reduceDeleteStatement(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
        
            $table     = null;
            $where     = null;
            $returning = null;
        
            foreach ($children as $child) {
                if (\is_string($child)) {
                    if ($table === null) {
                        $table = $child;
                    }
                    continue;
                }
        
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\WhereClause) {
                    $where = $child->expression;
                    continue;
                }
        
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\ReturningClause) {
                    $returning = $child;
                    continue;
                }
            }
        
            return new \Inilim\SqliteParser\Ast\Statement\DeleteStatement(
                table: $table ?? '',
                where: $where,
                returning: $returning,
            );
    }

    private static function reduceCreateTableStatement(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $table            = null;
            $ifNotExists      = false;
            $temporary        = false;
            $columns          = [];
            $tableConstraints = [];
            $withoutRowid     = false;
            $strict           = false;
            $asSelect         = null;

            $flat = [];
            $collect = static function ($items) use (&$collect, &$flat): void {
                foreach ($items as $item) {
                    if (\is_array($item)) {
                        $collect($item);
                    } else {
                        $flat[] = $item;
                    }
                }
            };
            $collect($children);

            foreach ($flat as $child) {
                if ($child === 'TEMP' || $child === 'TEMPORARY') {
                    $temporary = true;
                    continue;
                }
                if ($child === 'IF_NOT_EXISTS') {
                    $ifNotExists = true;
                    continue;
                }
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\TableOptions) {
                    $withoutRowid = $child->withoutRowid;
                    $strict = $child->strict;
                    continue;
                }
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\ColumnDefinition) {
                    $columns[] = $child;
                    continue;
                }
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement\TableConstraint) {
                    $tableConstraints[] = $child;
                    continue;
                }
                if ($child instanceof \Inilim\SqliteParser\Ast\Statement) {
                    $asSelect = $child;
                    continue;
                }
                if (\is_string($child) && $table === null) {
                    $table = $child;
                    continue;
                }
            }

            return new \Inilim\SqliteParser\Ast\Statement\CreateTableStatement(
                table: $table ?? '',
                columns: $columns,
                tableConstraints: $tableConstraints,
                ifNotExists: $ifNotExists,
                temporary: $temporary,
                withoutRowid: $withoutRowid,
                strict: $strict,
                asSelect: $asSelect,
            );
    }

