            $action    = '';
            $oldName   = null;
            $newName   = null;
            $column    = null;
            $idents    = [];
            $sawTo     = false;

            $flat = [];
            $collect = static function ($items) use (&$collect, &$flat): void {
                foreach ($items as $item) {
                    if (\is_array($item)) {
                        $collect($item);
                    } else {
                        $flat[] = $item;
                    }
                }
            };
            $collect($children);

            foreach ($flat as $item) {
                if ($item instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                    $u = \strtoupper($item->value);
                    if ($u === 'RENAME') {
                        $action = 'RENAME';
                    } elseif ($u === 'ADD') {
                        $action = 'ADD_COLUMN';
                    } elseif ($u === 'DROP') {
                        $action = 'DROP_COLUMN';
                    } elseif ($u === 'TO') {
                        $sawTo = true;
                    }
                    continue;
