                if ($item instanceof \Inilim\SqliteParser\Ast\Statement\ColumnDefinition) {
                    $column = $item;
                    continue;
                }
                if (\is_string($item)) {
                    if (!$tableSet) {
                        $table = $item;
                        $tableSet = true;
                    } else {
                        $idents[] = $item;
                    }
                    continue;
                }
