                        $v = $item->value;
                        $len = \strlen($v);
                        if ($len >= 2) {
                            $first = $v[0];
                            $last  = $v[$len - 1];
                            if ($first === '"' && $last === '"') {
                                $v = \substr($v, 1, -1);
                                $v = \str_replace('""', '"', $v);
                            } elseif ($first === '`' && $last === '`') {
                                $v = \substr($v, 1, -1);
                                $v = \str_replace('``', '`', $v);
                            } elseif ($first === '[' && $last === ']') {
                                $v = \substr($v, 1, -1);
                            }
